   "id": 527,
   "title": "Access to Higher Education Diploma (Health Professions)",
   "h1": "Access to Higher Education Diploma (Health Professions)",
   "subjectId": 2,
   "subject": "Access to HE Diplomas (Studied Online)",
   "mode": "Full time",
   "duration": "9 months",
